printf '%s\n' 'import argparse' '' 'parser = argparse.ArgumentParser(description="Show which config and environment were chosen")' 'parser.add_argument("config", help="path to the JSON config")' 'parser.add_argument("--env", choices=["dev", "staging", "prod"], default="dev", help="environment to use")' 'args = parser.parse_args()' 'print("file=%s env=%s" % (args.config, args.env))' > config_cli.py
